public class ProcessProperties_enterScope_TriageGen0Test {

    private ProcessProperties processProperties;

    @Mock
    private NodeTraversal mockNodeTraversal;

    @Mock
    private Node mockScopeNode;

    @Mock
    private Scope mockScope;

    // Mocking a Scope object since it's used in the logic
    interface Scope {
        void setScope(Node node);
    }

    // A helper class to represent the structure of the stack element
    // Since we cannot easily instantiate the internal anonymous classes of JSComp,
    // we use reflection to manipulate the symbolStack if necessary, 
    // or assume the structure based on the provided snippet.
    static class StackElement {
        Node scope;
    }

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        processProperties = new ProcessProperties();

        // Injecting a mock stack into the processProperties instance using reflection
        // because symbolStack is likely a private field in the real class.
        Deque<StackElement> symbolStack = new ArrayDeque<>();
        StackElement topElement = new StackElement();
        symbolStack.push(topElement);

        Field stackField = ProcessProperties.class.getDeclaredField("symbolStack");
        stackField.setAccessible(true);
        stackField.set(processProperties, symbolStack);
    }

    @Test
    public void enterScope_updatesScopeOnTopOfStack() throws Exception {
        // Arrange
        when(mockNodeTraversal.getScope()).thenReturn(mockScopeNode);

        // Access the stack element via reflection to verify the change
        Field stackField = ProcessProperties.class.getDeclaredField("symbolStack");
        stackField.setAccessible(true);
        Deque<StackElement> stack = (Deque<StackElement>) stackField.get(processProperties);
        StackElement topElement = stack.peek();

        // Act
        processProperties.enterScope(mockNodeTraversal);

        // Assert
        assertThat(topElement.scope).isEqualTo(mockScopeNode);
        verify(mockNodeTraversal).getScope();
    }

    @Test(expected = Exception.class)
    public void enterScope_throwsExceptionWhenStackIsEmpty() throws Exception {
        // Arrange
        Field stackField = ProcessProperties.class.getDeclaredField("symbolStack");
        stackField.setAccessible(true);
        stackField.set(processProperties, new ArrayDeque<StackElement>());

        // Act
        processProperties.enterScope(mockNodeTraversal);

        // Assert: Exception expected (NoSuchElementException from peek/pop)
    }
}

/**
 * Note: Since the internal implementation details of 'symbolStack' elements 
 * (specifically the field 'scope') are not provided in the snippet, 
 * this test assumes 'scope' is a field within the object stored in the stack.
 * In a real-world scenario, one would use the actual internal classes 
 * provided by the Google Closure Compiler library.
